package org.apache.commons.math.distribution;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.special.Gamma;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for PoissonDistributionImpl constructor.
 */
public class PoissonDistributionImpl_PoissonDistributionImpl_TriageGen0Test {

    @Test
    public void testConstructorWithValidParameters() {
        double p = 5.0;
        double epsilon = 1e-10;
        int maxIterations = 100;

        PoissonDistributionImpl distribution = new PoissonDistributionImpl(p, epsilon, maxIterations);

        assertEquals("Mean should be equal to p", p, distribution.getMean(), 1e-15);
    }

    @Test
    public void testConstructorWithPZeroThrowsException() {
        double p = 0.0;
        double epsilon = 1e-10;
        int maxIterations = 100;

        try {
            new PoissonDistributionImpl(p, epsilon, maxIterations);
            org.junit.Assert.fail("Expected MathIllegalArgumentException for p = 0");
        } catch (MathIllegalArgumentException e) {
            // Success: Exception is thrown as expected
        }
    }

    @Test
    public void testConstructorWithNegativePThrowsException() {
        double p = -1.0;
        double epsilon = 1e-10;
        int maxIterations = 100;

        try {
            new PoissonDistributionImpl(p, epsilon, maxIterations);
            org.junit.Assert.fail("Expected MathIllegalArgumentException for negative p");
        } catch (MathIllegalArgumentException e) {
            // Success: Exception is thrown as expected
        }
    }

    @Test
    public void testConstructorWithVerySmallPositiveP() {
        double p = 1e-12;
        double epsilon = 1e-10;
        int maxIterations = 100;

        PoissonDistributionImpl distribution = new PoissonDistributionImpl(p, epsilon, maxIterations);

        assertEquals("Mean should be equal to very small p", p, distribution.getMean(), 1e-15);
    }
}
